-- Queen West
INSERT INTO `neighbourhoods` (`slug`, `name`, `batch`, `sort_order`, `is_active`, `page_title`, `meta_desc`, `meta_keywords`, `og_image`, `og_image_alt`, `hero_eyebrow`, `hero_title`, `hero_text`, `hero_image`, `hero_image_alt`, `intro_title`, `intro_text`, `travel_title`, `travel_text`, `fact1_icon`, `fact1_label`, `fact1_text`, `fact2_icon`, `fact2_label`, `fact2_text`, `fact3_icon`, `fact3_label`, `fact3_text`, `fact4_icon`, `fact4_label`, `fact4_text`, `picks_title`, `picks_text`, `pick1_dish`, `pick1_note`, `pick2_dish`, `pick2_note`, `pick3_dish`, `pick3_note`, `faq1_q`, `faq1_a`, `faq2_q`, `faq2_a`, `faq3_q`, `faq3_a`, `closing_title`, `closing_text`, `neighbours`) VALUES
  ('kebab-in-queen-west-toronto', 'Queen West', 3, 4, 0, 'Queen West: Halal Charcoal Kebab 15 Minutes Down Strachan', 'The Trinity Bellwoods gates point straight at us. Fifteen minutes down Strachan to 133 Jefferson Ave, Liberty Village. Halal charcoal kebab, noon to 9 p.m.', 'kebab queen west, halal kebab queen street west, turkish restaurant queen west toronto', 'assets/img/hero-home.jpg', 'Adana and kofte skewers over charcoal at Unika Kebab', 'Down Strachan from the Trinity Bellwoods gates', 'Queen West eats at ten. Our charcoal is out by nine.', 'So make it the early half of the night. Unika Kebab is at 133 Jefferson Ave in Liberty Village, about fifteen minutes down Strachan from the Trinity Bellwoods gates. Halal, charcoal-grilled to order, noon to 9 p.m. seven days.', 'assets/img/bg-parchment.jpg', 'Unika Kebab, ten minutes down Strachan Ave from Queen West', 'The strip is built for evenings out, not for dinner', 'Strachan Avenue ends at Queen Street, and what stands there is a pair of stone gates — the last of Trinity College, founded on that spot in 1851 by Bishop John Strachan and restored in 2007. Stand at the gates and look south. That is the line down to us: roughly 1.2 km, fifteen minutes at a pace nobody would call brisk.

West Queen West runs Bathurst to Gladstone with more than four hundred businesses along it — galleries, secondhand racks, the Theatre Centre in the 1909 Queen–Lisgar Carnegie library at 1115 Queen, the Drake Underground in the basement at 1150. The strip is built for evenings out. It is not built for eating properly before one. That is where we come in, from fifteen minutes away: Unika Kebab is on Jefferson Ave, just south of King Street West in Liberty Village, beside Allan A. Lamport Stadium at 1155 King St W. Different neighbourhood, same night.

The catch is our hours. Noon to nine, seven days, and nine means the coals are already out. So we are a 6:30 plan, not an 11:30 one. Eat, walk back up Strachan, and you reach Queen with a real dinner behind you instead of whatever the bar keeps behind glass. Family run, all halal, and nothing goes on the charcoal until you have ordered it.', 'Strachan south, or one bus if you would rather not walk', 'On foot, start at the gates and go south on Strachan to King Street West, then turn right. You pass Shaw, Joe Shuster Way, Atlantic and Fraser, then Lamport Stadium — and Jefferson is the street immediately past it. About 1.2 km all in.

By bus, the 63 Ossington runs east along Queen Street West from Ossington to Shaw before it turns south, so you can board it on Queen itself, and it finishes its run inside Liberty Village by way of Liberty Street and Atlantic Ave. From the Spadina end, take the 501 Queen west to Strachan Ave and walk down. One thing for the winter: from 1 November 2026 the 504 King streetcar diverts onto Queen West between Spadina and Roncesvalles while King Street is rebuilt, with 504C buses covering King. Check ttc.ca before you set out.', 'fa-solid fa-person-walking', 'Straight down Strachan', 'Strachan Avenue ends at the old Trinity College gates on Queen. South from there to King Street West, then right, is roughly 1.2 km — call it fifteen minutes.', 'fa-solid fa-bus-simple', 'The 63 Ossington boards on Queen', 'Southbound it runs east on Queen St W from Ossington to Shaw, then down to King and into Liberty Village, looping via Liberty Street and Atlantic Ave. One bus, no transfer.', 'fa-solid fa-clock', 'Noon to 9 p.m., seven days', 'The grill is off at nine. That makes us dinner before a curtain at the Theatre Centre, 1115 Queen St W, or a set downstairs at the Drake — never a stop on the way home.', 'fa-solid fa-triangle-exclamation', 'The King car moves to Queen in November', 'From 1 November 2026 the 504 King diverts along Queen St W between Spadina and Roncesvalles for watermain and track work; 504C buses cover King St W. Check ttc.ca.', 'A whole dinner for what the strip charges for small plates', 'Queen West does small plates and shared boards. This is the opposite of that: one large plate, something green next to it, something sweet for the walk back up. Roughly what two drinks on Ossington cost. The kofte and Adana skewers are there if you want them.', 'Plates (Platter)::Chicken Shawarma', 'The $19.99 plate is the full one — rice, salad, sauce. It wants a table, so eat it here rather than carrying it back up Strachan in a bag.', 'Sides::Tabuli Bowl', 'Parsley, bulgur, lemon. Order it if you are sitting in the Theatre Centre an hour later and would rather not spend the first act digesting.', 'Dessert::Baklava', 'The one thing here that is better walking than sitting. Dessert on Queen West mostly means taking a table again; this goes north up Strachan with you.', 'Can I come after a show at the Drake Underground?', 'No — we close at 9 p.m., seven days, and by then the charcoal is out. Anything with an evening door at 1150 Queen St W puts you at our counter after we have locked it. Flip the order instead: eat at six or half past, then walk back up Strachan or Dufferin and be on Queen with time in hand. It is a better dinner than the one you would have had at eleven anyway.', 'How do I get down from the Graffiti Alley end of Queen West?', 'Graffiti Alley is Rush Lane, running south of Queen from Spadina to Portland — the far east end of the strip, and too far to walk. Take the 501 Queen west, get off at Queen St W at Strachan Ave, then go south to King Street West and west to Jefferson. About half an hour door to door, most of it sitting down.', 'Can I order ahead and pick it up on the way down?', 'Yes, and on a night with a curtain time that is the way to do it. Order through our Square page or on Google, or phone 416-516-2087, and it is ready when you get to 133 Jefferson Ave. Pickup is the only way we do it — no delivery, and we are not on any of the apps. Everything is grilled from raw once the order lands, so ordering ahead genuinely buys you the time.', 'Come down at six, not at eleven', 'Fifteen minutes down Strachan from the Trinity Bellwoods gates. One 63 Ossington bus if you would rather sit, and it boards on Queen Street itself. Halal, family run, charcoal lit at noon and out at nine, seven days a week. 133 Jefferson Ave, Toronto. 416-516-2087, or order ahead online for pickup.', 'kebab-in-parkdale-toronto,kebab-in-king-west-toronto')
